class Solution {
public:
    int houseOfCards(int n) {
        vector<int> dp(n + 1);
        dp[0] = 1;
        for (int i = 1; 3 * i - 1 <= n; ++i) {
            int cost = 3 * i - 1;
            for (int sum = n; sum >= cost; --sum)
                dp[sum] += dp[sum - cost];
        }
        return dp[n];
    }
};
